    #[test]
    fn compatibility_queries_delegate_to_component_descriptor_catalog() {
        assert_eq!(
            vanilla_data_component_resource_id_for_type_id(0),
            Some("minecraft:custom_data")
        );
        assert_eq!(
            vanilla_data_component_resource_id_for_type_id(109),
            Some("minecraft:shulker/color")
        );
        assert_eq!(vanilla_data_component_resource_id_for_type_id(-1), None);
        assert_eq!(vanilla_data_component_resource_id_for_type_id(110), None);
        assert!(vanilla_data_component_type_is_persistent(0));
        assert!(!vanilla_data_component_type_is_persistent(20));
        assert!(!vanilla_data_component_type_is_persistent(41));
        assert!(!vanilla_data_component_type_is_persistent(48));
    }

    #[test]
    fn predicate_type_catalog_is_complete_contiguous_and_unique() {
        assert_eq!(VANILLA_DATA_COMPONENT_PREDICATE_TYPES.len(), 15);
        let mut constant_names = HashSet::new();
        let mut resource_ids = HashSet::new();
        for (type_id, entry) in VANILLA_DATA_COMPONENT_PREDICATE_TYPES.iter().enumerate() {
            assert_eq!(entry.type_id, type_id as i32);
            assert!(constant_names.insert(entry.constant_name));
            assert!(resource_ids.insert(entry.resource_id));
            assert!(entry.resource_id.starts_with("minecraft:"));
        }
        assert_eq!(
            vanilla_data_component_predicate_resource_id(0),
            Some("minecraft:damage")
        );
        assert_eq!(
            vanilla_data_component_predicate_resource_id(14),
            Some("minecraft:villager/variant")
        );
        assert_eq!(vanilla_data_component_predicate_resource_id(-1), None);
        assert_eq!(vanilla_data_component_predicate_resource_id(15), None);
        assert_eq!(VANILLA_DATA_COMPONENT_PREDICATE_DAMAGE_TYPE_ID, 0);
        assert_eq!(VANILLA_DATA_COMPONENT_PREDICATE_CONTAINER_TYPE_ID, 5);
        assert_eq!(
            VANILLA_DATA_COMPONENT_PREDICATE_VILLAGER_VARIANT_TYPE_ID,
            14
        );
    }

    fn starts_with_integer_literal(value: &str) -> bool {
        let mut characters = value.chars();
        let Some(first) = characters.next() else {
            return false;
        };
        first.is_ascii_digit()
            || (first == '-'
                && characters
                    .next()
                    .is_some_and(|character| character.is_ascii_digit()))
    }

    fn contains_numeric_dialog_component_type_id_reference(source: &str) -> bool {
        let compact: String = source
            .chars()
            .filter(|character| !character.is_whitespace())
            .collect();
        let numeric_component_or_predicate_field = ["component_type_id:", "predicate_type_id:"]
            .iter()
            .any(|field| {
                compact.match_indices(field).any(|(offset, _)| {
                    let boundary = offset == 0
                        || compact[..offset]
                            .chars()
                            .next_back()
                            .is_some_and(|character| {
                                !character.is_ascii_alphanumeric() && character != '_'
                            });
                    boundary && starts_with_integer_literal(&compact[offset + field.len()..])
                })
            });
        let numeric_patch_or_reference_construction = [
            "DialogDataComponentPatchEntryState{type_id:",
            "DialogDataComponentReferenceState{type_id:",
        ]
        .iter()
        .any(|prefix| {
            compact
                .match_indices(prefix)
                .any(|(offset, _)| starts_with_integer_literal(&compact[offset + prefix.len()..]))
        });
        let numeric_patch_summary = [
            "component_patch.added_type_ids,vec![",
            "component_patch.removed_type_ids,vec![",
        ]
        .iter()
        .any(|prefix| {
            compact
                .match_indices(prefix)
                .any(|(offset, _)| starts_with_integer_literal(&compact[offset + prefix.len()..]))
        });
        numeric_component_or_predicate_field
            || numeric_patch_or_reference_construction
            || numeric_patch_summary
    }

    #[test]
    fn numeric_dialog_component_type_id_guard_covers_component_and_predicate_fields() {
        assert!(contains_numeric_dialog_component_type_id_reference(
            "component_type_id: 12,"
        ));
        assert!(contains_numeric_dialog_component_type_id_reference(
            "predicate_type_id: 5,"
        ));
        assert!(contains_numeric_dialog_component_type_id_reference(
            "DialogDataComponentPatchEntryState { type_id: 19 }"
        ));
        assert!(contains_numeric_dialog_component_type_id_reference(
            "DialogDataComponentReferenceState { type_id: 1 }"
        ));
        assert!(contains_numeric_dialog_component_type_id_reference(
            "assert_eq!(summary.component_patch.added_type_ids, vec![6]);"
        ));
        assert!(!contains_numeric_dialog_component_type_id_reference(
            "component_type_id: VANILLA_DATA_COMPONENT_RARITY_TYPE_ID,"
        ));
        assert!(!contains_numeric_dialog_component_type_id_reference(
            "predicate_type_id: VANILLA_DATA_COMPONENT_PREDICATE_CONTAINER_TYPE_ID,"
        ));
        assert!(!contains_numeric_dialog_component_type_id_reference("DialogDataComponentPatchEntryState { type_id: VANILLA_DATA_COMPONENT_REPAIR_COST_TYPE_ID }"));
        assert!(!contains_numeric_dialog_component_type_id_reference("DialogDataComponentReferenceState { type_id: VANILLA_DATA_COMPONENT_MAX_STACK_SIZE_TYPE_ID }"));
        assert!(!contains_numeric_dialog_component_type_id_reference("assert_eq!(summary.component_patch.added_type_ids, vec![VANILLA_DATA_COMPONENT_CUSTOM_NAME_TYPE_ID]);"));
        assert!(!contains_numeric_dialog_component_type_id_reference(
            "particle_type_id: 5,"
        ));
    }

    #[test]
    fn dialog_component_fixtures_do_not_restore_numeric_type_ids() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if contains_numeric_dialog_component_type_id_reference(&source) {
                    violations.push(format!(
                        "{}: numeric dialog component type id",
                        path.display()
                    ));
                }
            }
        }
        let mut violations = Vec::new();
        let crates = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        visit(
            &crates.join("bbb-world/src/client/dialog/body"),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "dialog component fixtures restored numeric type ids:\n{}",
            violations.join("\n")
        );
    }
